-- Generated by drizzle-kit, then reviewed and extended by hand (29 October 2026).
--
-- Enforces the role relationships that 0004 added and 0005 filled, so direct
-- SQL can't break them either (R1.2, R1.3):
--   * every branch has an Owner;
--   * at most one Developer at any moment;
--   * an active staff profile grants exactly the role it records, its title
--     follows that role, and Staff and Receptionists name their branch while
--     a Manager's profile names none.
-- The hand-written part below adds deferred constraint triggers that check
-- the final state at commit for every person a change touched: an Owner owns
-- a branch; a Manager manages one and has an active profile; a Receptionist
-- or Staff member has an active profile; the last Developer isn't removed.
-- Drizzle can't declare triggers, so the snapshot doesn't record them.
--
-- Run after 0005 on a database whose data passed its checks. A database with
-- branches but no Owner account fails the first statement, by design.
ALTER TABLE "branch" ALTER COLUMN "owner_user_id" SET NOT NULL;--> statement-breakpoint
CREATE UNIQUE INDEX "user_one_developer" ON "user" USING btree ("role") WHERE role = 'developer';--> statement-breakpoint
ALTER TABLE "staff_profile" ADD CONSTRAINT "staff_profile_active_witness_check" CHECK (is_active = (role_witness IS NOT NULL));--> statement-breakpoint
ALTER TABLE "staff_profile" ADD CONSTRAINT "staff_profile_designation_matches_role_check" CHECK (role_witness IS NULL
        OR (role_witness = 'manager' AND designation = 'manager')
        OR (role_witness = 'receptionist' AND designation = 'receptionist')
        OR (role_witness = 'staff' AND designation IN ('stylist', 'therapist')));--> statement-breakpoint
ALTER TABLE "staff_profile" ADD CONSTRAINT "staff_profile_branch_by_role_check" CHECK (role_witness IS NULL
        OR (role_witness = 'manager' AND branch_id IS NULL)
        OR (role_witness IN ('staff', 'receptionist') AND branch_id IS NOT NULL));--> statement-breakpoint
-- The relationships one person's role needs. Raised as check_violation with
-- CONSTRAINT 'role_relationships', which the app reports as a stale change.
CREATE FUNCTION "public"."assert_role_relationships"(person text) RETURNS void
LANGUAGE plpgsql AS $$
DECLARE
  person_role text;
BEGIN
  -- Serialize concurrent checks for the same person, so two transactions that
  -- each remove one of a shared Manager's branches can't both pass
  -- (spike-results.md §2). NO KEY UPDATE doesn't block foreign-key checks.
  SELECT role INTO person_role FROM "user" WHERE id = person FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF person_role = 'owner' THEN
    IF NOT EXISTS (SELECT 1 FROM branch WHERE owner_user_id = person) THEN
      RAISE EXCEPTION 'Owner % owns no branch', person
        USING ERRCODE = 'check_violation', CONSTRAINT = 'role_relationships';
    END IF;
  ELSIF person_role = 'manager' THEN
    IF NOT EXISTS (SELECT 1 FROM branch WHERE manager_user_id = person) THEN
      RAISE EXCEPTION 'Manager % manages no branch', person
        USING ERRCODE = 'check_violation', CONSTRAINT = 'role_relationships';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM staff_profile
      WHERE user_id = person AND is_active AND role_witness = 'manager'
    ) THEN
      RAISE EXCEPTION 'Manager % has no active profile', person
        USING ERRCODE = 'check_violation', CONSTRAINT = 'role_relationships';
    END IF;
  ELSIF person_role IN ('receptionist', 'staff') THEN
    IF NOT EXISTS (
      SELECT 1 FROM staff_profile
      WHERE user_id = person AND is_active AND role_witness = person_role
    ) THEN
      RAISE EXCEPTION '% % has no active profile', person_role, person
        USING ERRCODE = 'check_violation', CONSTRAINT = 'role_relationships';
    END IF;
  END IF;
END;
$$;--> statement-breakpoint
CREATE FUNCTION "public"."user_role_relationships_check"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP <> 'DELETE' THEN
    PERFORM public.assert_role_relationships(NEW.id);
  END IF;
  -- Removing the Developer needs a replacement in the same transaction; the
  -- unique index already stops a second one.
  IF TG_OP <> 'INSERT' THEN
    IF OLD.role = 'developer' AND NOT EXISTS (SELECT 1 FROM "user" WHERE role = 'developer') THEN
      RAISE EXCEPTION 'The Developer can only be replaced, not removed'
        USING ERRCODE = 'check_violation', CONSTRAINT = 'one_developer';
    END IF;
  END IF;
  RETURN NULL;
END;
$$;--> statement-breakpoint
CREATE FUNCTION "public"."branch_role_relationships_check"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  -- New references are valid by the role-qualified foreign keys; the people
  -- a branch no longer names may have lost their last branch.
  IF OLD.owner_user_id IS NOT NULL THEN
    PERFORM public.assert_role_relationships(OLD.owner_user_id);
  END IF;
  IF OLD.manager_user_id IS NOT NULL THEN
    PERFORM public.assert_role_relationships(OLD.manager_user_id);
  END IF;
  RETURN NULL;
END;
$$;--> statement-breakpoint
CREATE FUNCTION "public"."staff_profile_role_relationships_check"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  PERFORM public.assert_role_relationships(OLD.user_id);
  IF TG_OP = 'UPDATE' THEN
    IF NEW.user_id IS DISTINCT FROM OLD.user_id THEN
      PERFORM public.assert_role_relationships(NEW.user_id);
    END IF;
  END IF;
  RETURN NULL;
END;
$$;--> statement-breakpoint
CREATE CONSTRAINT TRIGGER "user_role_relationships"
AFTER INSERT OR UPDATE OF "role" OR DELETE ON "user"
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION "public"."user_role_relationships_check"();--> statement-breakpoint
CREATE CONSTRAINT TRIGGER "branch_role_relationships"
AFTER UPDATE OF "owner_user_id", "manager_user_id" OR DELETE ON "branch"
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION "public"."branch_role_relationships_check"();--> statement-breakpoint
CREATE CONSTRAINT TRIGGER "staff_profile_role_relationships"
AFTER UPDATE OR DELETE ON "staff_profile"
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION "public"."staff_profile_role_relationships_check"();
